do $$
declare v_doc_id uuid; v_item record;
begin
 select id into v_doc_id from public.regulation_documents where document_code='DP-SR-HR-001' and revision='003' and is_shared_standard=true order by created_at desc limit 1;
 if v_doc_id is null then raise exception 'Shared standard DP-SR-HR-001 revision 003 not found'; end if;
 for v_item in select * from jsonb_to_recordset($clauses$[{"section_number":"10.1.1","content_text":"เพื่อใช้เป็นแนวทางในการปฏิบัติเกี่ยวกับวินัย พนักงานผู้ใดฝ่าฝืนให้ถือว่าเป็นการกระทำผิดวินัยและได้รับโทษทางวินัยตามควรแก่กรณี","source_page":1,"sort_order":46},{"section_number":"10.1.2","content_text":"เพื่อใช้เป็นแนวทางปฏิบัติของผู้บังคับบัญชาในการพิจารณา ส่งเสริม แก้ไข หรือปรับปรุงความประพฤติของผู้ใต้บังคับบัญชา","source_page":1,"sort_order":47},{"section_number":"10.1.3","content_text":"เพื่อให้เกิดความเป็นธรรมต่อพนักงาน","source_page":1,"sort_order":48},{"section_number":"10.1.4","content_text":"เพื่อช่วยส่งเสริมให้การดำเนินงานของบริษัทบรรลุวัตถุประสงค์ด้วยความมีระเบียบถูกต้องตามกฎหมาย และก่อให้เกิดความสงบสุขร่วมกัน","source_page":1,"sort_order":49},{"section_number":"10.3.1","content_text":"ทุจริตต่อหน้าที่ หรือกระทำความผิดอาญาโดยเจตนาต่อบริษัท","source_page":2,"sort_order":50},{"section_number":"10.3.2","content_text":"กระทำการใด ๆ ที่เป็นการจงใจทำให้บริษัทได้รับความเสียหาย","source_page":2,"sort_order":51},{"section_number":"10.3.3","content_text":"ฝ่าฝืนระเบียบข้อบังคับเกี่ยวกับการทำงาน หรือระเบียบ หรือคำสั่งของผู้บังคับบัญชาอันชอบด้วยกฎหมายและเป็นธรรม และบริษัทได้ตักเตือนเป็นหนังสือแล้ว โดยหนังสือเตือนนั้นมีผลบังคับไม่เกิน 1 ปี นับตั้งแต่วันที่พนักงานได้กระทำความผิด เว้นแต่กรณีร้ายแรงบริษัทไม่จำเป็นต้องตักเตือน","source_page":2,"sort_order":52},{"section_number":"10.3.4","content_text":"ละทิ้งหน้าที่เป็นเวลา 3 วันทำงานติดต่อกันไม่ว่าจะมีวันหยุดคั่นหรือไม่ก็ตาม โดยไม่มีเหตุอันควร","source_page":2,"sort_order":53},{"section_number":"10.3.5","content_text":"กระทำโดยประมาท เลินเล่อ เป็นเหตุให้บริษัทได้รับความเสียหายอย่างร้ายแรง","source_page":2,"sort_order":54},{"section_number":"10.3.6","content_text":"ได้รับโทษจำคุกตามคำพิพากษาถึงที่สุดให้จำคุก เว้นแต่เป็นโทษสำหรับความผิดที่ได้กระทำโดยประมาทหรือความผิดลหุโทษ ต้องเป็นกรณีที่เป็นเหตุให้นายจ้างได้รับความเสียหาย","source_page":3,"sort_order":55},{"section_number":"10.4.1","content_text":"เตือนด้วยวาจา","source_page":3,"sort_order":56},{"section_number":"10.4.2","content_text":"เตือนเป็นหนังสือ","source_page":3,"sort_order":57},{"section_number":"10.4.3","content_text":"พักงานโดยไม่ได้รับค่าจ้าง ไม่เกิน 6 วัน","source_page":3,"sort_order":58},{"section_number":"10.4.4","content_text":"เลิกจ้างโดยปลดออก ให้ออก หรือไล่ออก","source_page":3,"sort_order":59},{"section_number":"10.5.1","content_text":"เตือนด้วยวาจา และการเตือนเป็นหนังสือ ผู้บังคับบัญชาโดยตรงของพนักงานผู้กระทำผิด เป็นผู้พิจารณาและดำเนินการลงโทษ","source_page":3,"sort_order":60},{"section_number":"10.5.2","content_text":"การลงโทษด้วยการพักงานโดยไม่ได้รับค่าจ้าง ผู้บังคับบัญชาโดยตรงร่วมกับผู้บังคับบัญชาสูงกว่า 1 ระดับของพนักงานผู้กระทำผิด เป็นผู้ร่วมกันดำเนินการพิจารณาและลงโทษทางวินัย และเมื่อลงโทษแล้วให้รายงานต่อผู้บังคับบัญชาสูงสุดในหน่วยงานรับทราบ","source_page":3,"sort_order":61},{"section_number":"10.5.3","content_text":"การลงโทษด้วยการเลิกจ้างโดยไม่จ่ายค่าชดเชย ผู้บังคับบัญชาโดยตรง ร่วมกับผู้บังคับบัญชาเหนือขึ้นไปทุกระดับชั้นของหน่วยงานของพนักงานผู้กระทำผิด และผู้จัดการฝ่ายบริหารทรัพยากรบุคคล ร่วมกันพิจารณาการลงโทษ และแจ้งให้กับกรรมการผู้จัดการลงนามอนุมัติ","source_page":3,"sort_order":62},{"section_number":"10.6.1","content_text":"การลงโทษด้วยการเตือนด้วยวาจาและบันทึกไว้ การว่ากล่าวตักเตือนด้วยวาจาจะกระทำโดยผู้บังคับบัญชาโดยตรงของผู้กระทำผิด ความผิดในขั้นนี้ไม่ร้ายแรง และไม่ก่อให้เกิดผลเสียหายแก่บริษัท ผู้จัดการฝ่ายบริหารทรัพยากรบุคคลจะเป็นผู้ให้คำปรึกษาแนะนำ และฝ่ายบริหารทรัพยากรบุคคลจะจัดเตรียมเอกสารการลงโทษให้กับผู้บังคับบัญชา โดยระบุรายละเอียดเกี่ยวกับการกระทำผิด ได้แก่ ผู้กระทำผิด ลักษณะของความผิด สถานที่กระทำผิด วันที่กระทำผิด และให้ผู้บังคับบัญชาโดยตรงเป็นผู้ว่ากล่าวตักเตือนพนักงานผู้กระทำผิด และให้พนักงานผู้กระทำผิดลงนามยอมรับเกี่ยวกับการกระทำผิดของตน แล้วจัดส่งเอกสารมาเก็บที่ฝ่ายบริหารทรัพยากรบุคคล","source_page":3,"sort_order":63},{"section_number":"10.6.2","content_text":"การลงโทษด้วยการเตือนเป็นหนังสือ เป็นการลงโทษหลังจากที่การตักเตือนด้วยวาจาไม่ประสบผล หรือมีการกระทำความผิดรุนแรงเกินกว่าจะตักเตือนด้วยวาจา หรือทำผิดซ้ำเรื่องเดิมในเวลาไล่เลี่ยกัน และยังอยู่ในระยะเวลาตามกำหนดของการลงโทษ ซึ่งความผิดดังกล่าวยังไม่ก่อให้เกิดความเสียหายร้ายแรง หรือผลเสียหายโดยตรงต่อบริษัท แต่อาจก่อให้เกิดความรำคาญกับผู้เกี่ยวข้องหรือเกิดความล่าช้าในการปฏิบัติงาน การพิจารณาการลงโทษในชั้นนี้เป็นอำนาจของผู้บังคับบัญชาของผู้กระทำผิด โดยผู้จัดการฝ่ายบริหารทรัพยากรบุคคลจะเป็นผู้ให้คำปรึกษาแนะนำ และฝ่ายบริหารทรัพยากรบุคคลจะจัดเตรียมเอกสารการลงโทษให้กับผู้บังคับบัญชา โดยระบุรายละเอียดเกี่ยวกับการกระทำผิด ได้แก่ ผู้กระทำผิด ลักษณะของความผิด สถานที่กระทำผิด วันที่กระทำผิด และให้ผู้บังคับบัญชาโดยตรงเป็นผู้ว่ากล่าวตักเตือนพนักงานผู้กระทำผิด และให้พนักงานผู้กระทำผิดลงนามยอมรับเกี่ยวกับการกระทำผิดของตน แล้วจัดส่งเอกสารมาเก็บที่ฝ่ายบริหารทรัพยากรบุคคล","source_page":4,"sort_order":64},{"section_number":"10.6.3","content_text":"การลงโทษด้วยการพักงานไม่จ่ายค่าจ้าง ไม่เกิน 6 วัน เป็นการลงโทษที่รุนแรงกว่าการเตือนด้วยวาจาและการเตือนเป็นหนังสือ เมื่อปรากฏเจตนาชัดแจ้งในการกระทำผิด หรือเป็นการทำผิดวินัยซ้ำในเรื่องเดิมบ่อย ๆ ภายในระยะเวลาไล่เลี่ยกัน และความผิดดังกล่าวก่อให้เกิดความเสียหายต่อบริษัทไม่ว่าจะเป็นด้านทรัพย์สินหรือชื่อเสียง การดำเนินการประกอบด้วย 3 ขั้นตอน: ขั้นที่ 1 ผู้บังคับบัญชาโดยตรงบันทึกรายละเอียดความผิด เหตุผลในการลงโทษ และสรุปผลสอบสวนส่งผู้บังคับบัญชาระดับเหนือกว่า; ขั้นที่ 2 ผู้บังคับบัญชาระดับเหนือกว่าพิจารณาร่วมกับผู้จัดการฝ่ายบริหารทรัพยากรบุคคล สอบสวนข้อเท็จจริงจากผู้เกี่ยวข้อง และเสนอผู้บังคับบัญชาสูงสุดของหน่วยงาน; ขั้นที่ 3 ฝ่ายบริหารทรัพยากรบุคคลจัดเตรียมหนังสือแจ้งการลงโทษ ส่งให้ผู้บังคับบัญชาระดับผู้จัดการเพื่อให้พนักงานลงนามยอมรับ แล้วส่งเอกสารคืนฝ่ายบริหารทรัพยากรบุคคล","source_page":4,"sort_order":65},{"section_number":"10.6.4","content_text":"การลงโทษด้วยการเลิกจ้างโดยไม่จ่ายค่าชดเชย จะกระทำเมื่อการลงโทษด้วยวาจา เตือนเป็นหนังสือ หรือพักงานโดยไม่ได้รับค่าจ้างในลักษณะเดิมไม่ประสบผล ยกเว้นกรณีความผิดร้ายแรงแม้เป็นการกระทำผิดครั้งแรก ขั้นที่ 1–2 ดำเนินการเช่นเดียวกับข้อ 10.6.3; ขั้นที่ 3 ผู้บังคับบัญชาระดับสูงสุดของหน่วยงานพิจารณาเรื่องทั้งหมด และเสนอกรรมการผู้จัดการ; ขั้นที่ 4 กรรมการผู้จัดการสั่งการผ่านผู้บังคับบัญชาสูงสุดไปยังฝ่ายบริหารทรัพยากรบุคคลเพื่อจัดเตรียมหนังสือแจ้งความผิดและลงโทษหรือหนังสือเลิกจ้าง โดยผู้มีอำนาจลงนามคือกรรมการผู้จัดการหรือผู้ที่ได้รับมอบหมายเป็นลายลักษณ์อักษร","source_page":4,"sort_order":66},{"section_number":"10.7","content_text":"พักงานเพื่อการสอบสวน ในกรณีที่พนักงานกระทำความผิดและบริษัทเห็นสมควรให้มีการสอบสวน กรรมการผู้จัดการหรือผู้มีอำนาจที่ได้รับมอบหมายอาจสั่งพักงานเป็นหนังสือได้ไม่เกิน 7 วัน เพื่อสอบสวนโดยระบุความผิดให้พนักงานทราบ ระหว่างพักงานบริษัทจะจ่ายค่าจ้างเท่ากับครึ่งหนึ่งของค่าจ้างในวันทำงานปกติ หากผลสอบสวนปรากฏว่าพนักงานไม่ผิด บริษัทจะจ่ายค่าจ้างส่วนที่ขาดอีกครึ่งหนึ่งพร้อมดอกเบี้ยร้อยละ 15 ต่อปี","source_page":4,"sort_order":67}]$clauses$::jsonb) as x(section_number text,content_text text,source_page integer,sort_order integer)
 loop
  if not exists(select 1 from public.regulation_sections where document_id=v_doc_id and section_number=v_item.section_number) then
   insert into public.regulation_sections(document_id,company_id,category_code,section_number,heading,content_text,source_page,sort_order)
   values(v_doc_id,'3242719e-4cd2-44d5-8943-60e7fc1fb267','discipline',v_item.section_number,'ข้อ '||v_item.section_number,v_item.content_text,v_item.source_page,v_item.sort_order);
  end if;
 end loop;
end $$;